/*
 * Minimal REPL/qjscalc stubs for the G5 Leopard build.
 *
 * Upstream qjs links in two precompiled-bytecode blobs — the interactive REPL
 * (repl.c) and the bignum calculator (qjscalc.c) — generated by bootstrapping
 * qjsc against repl.js / qjscalc.js. Those .js sources are NOT shipped in this
 * repo, so qjs cannot link as-is (the G4 Makefile shares this gap).
 *
 * Claude Code runs scripts non-interactively (`qjs claude.js`), which never
 * touches the embedded REPL. Providing empty blobs (size 0) lets qjs link and
 * run scripts; only the interactive `qjs` prompt and built-in `qjscalc` are
 * unavailable. Build a full REPL later by adding repl.js/qjscalc.js + a qjsc
 * bootstrap rule.
 */
#include <stdint.h>

const uint8_t qjsc_repl[1] = { 0 };
const uint32_t qjsc_repl_size = 0;

const uint8_t qjsc_qjscalc[1] = { 0 };
const uint32_t qjsc_qjscalc_size = 0;
